function source(pieces) {
  const doc = docs[pieces[0].doc];
  if (pieces.some(p => p.doc !== pieces[0].doc)) throw Error('Mixed source group');
  return { file: doc.file, title: doc.title, pages: [...new Set(pieces.map(p => p.page))], sections: [...new Set(pieces.map(p => p.section))], evidence: pieces.map(p => p.text) };
}
const cards = [];
function add(n, question, answer, primary, ...related) {
  cards.push({ id: `${docs.chip.articleId}-${n}`, articleId: docs.chip.articleId,
    question, answer, source: source(primary), kind: related.length ? 'synthesis' : 'direct',
    ...(related.length ? { relatedSources: related.map(pieces => ({ articleId: docs[pieces[0].doc].articleId, source: source(pieces) })) } : {}) });
}

add(9, 'Que contradição entre mercado consumidor, produção e pesquisa a introdução de Games Made Elsewhere descreve para o Brasil?',
'A introdução relata um mercado brasileiro de [[103 milhões de jogadores]], mas afirma que sua contribuição ao desenvolvimento e à pesquisa de jogos não acompanha essa dimensão. Ao lado de uma comunidade de IHC ativa, menciona poucas oportunidades de financiamento para pesquisa de jogos pela perspectiva de IHC, outras prioridades nacionais e uma indústria doméstica jovem, pequena e orientada à exportação. O ponto é a [[assimetria entre consumo e capacidade de criação/pesquisa]]. São dados e caracterizações mobilizados pelo artigo de 2025, não uma atualização estatística feita por este cartão.', [c.market]);
add(10, 'Como Games Made Elsewhere liga padrões enganosos à monetização predatória sem reduzir o problema à simples existência de jogos pagos?',
'O artigo descreve padrões enganosos como projetos manipulativos que exploram vieses para ganho comercial às custas do usuário. Na discussão sobre jogos, destaca a intensificação pela [[monetização predatória que obscurece custos reais]], e não a mera cobrança de um preço. Menciona diferentes danos e a possibilidade de agravar problemas relacionados ao Gaming Disorder. A formulação é de risco e possibilidade, não de diagnóstico de todo jogador nem de demonstração de que qualquer monetização cause esses efeitos. O mecanismo criticado é o ganho obtido por [[exploração e opacidade]].', [c.monetization]);
add(11, 'Por que seria incorreto interpretar Games Made Elsewhere como a tese de que exploração digital só ocorre no Sul Global?',
'O texto afirma expressamente que jogos em contextos [[WEIRD também contêm padrões enganosos]] e que exploração digital não é geograficamente exclusiva. A pergunta que organiza o argumento é outra: se diferenças não-WEIRD alteram a [[natureza e a magnitude do dano]]. Assim, o artigo propõe que danos podem ser sistemicamente ampliados em grandes mercados do Sul Global, sem negar riscos nas sociedades onde muitos jogos são desenvolvidos. Essa é uma tese contextual argumentada no trabalho, não uma comparação causal nova realizada com amostras de jogadores dos dois grupos.', [c.geography]);
add(12, 'Na formulação do creator-consumer divide, por que uma explicação baseada apenas na má intenção de um desenvolvedor seria insuficiente?',
'A definição do artigo coloca no centro uma separação estrutural entre contextos de criação e consumo: as vulnerabilidades são [[sistêmicas e preexistentes]]. Sua capitalização pode ocorrer por direcionamento deliberado ou por [[automação indiferente]]. Portanto, a lente não depende de provar a intenção individual de cada programador para examinar danos de sistemas inseridos em contextos desiguais. Isso não demonstra que qualquer automação seja exploratória; identifica duas vias pelas quais vulnerabilidades já existentes podem ser aproveitadas e desloca a discussão para condições estruturais de projeto e implantação.', [c.construct]);
add(13, 'Qual papel o caráter de entretenimento desempenha na primeira dimensão do creator-consumer divide, e qual qualificação acompanha essa proposta?',
'O artigo sustenta que o entretenimento pode [[reduzir a vigilância crítica]], tornando práticas manipulativas mais facilmente aceitas como “parte do jogo”. Propõe que essa suscetibilidade pode ser ampliada quando parcela significativa da população não dispõe de defesas cognitivas fundamentais, condição relacionada a problemas sociais profundos. A explicação é contextual e usa linguagem de possibilidade; não autoriza concluir que todo entretenimento elimina julgamento crítico ou que todos os jogadores de um país tenham a mesma vulnerabilidade. O argumento combina a apresentação lúdica da interação com [[condições sociais anteriores ao uso]].', [c.guard]);
add(14, 'Como a comparação de pobreza entre Brasil e Estados Unidos é usada no argumento de Games Made Elsewhere, e o que ela não permite concluir?',
'O artigo apresenta taxas de [[11,1% nos Estados Unidos e 27,4% no Brasil]] para ilustrar uma precariedade mais disseminada no contexto brasileiro e a associa à literatura sobre decisão prejudicada pelo estresse. A função da comparação é situar uma assimetria de condições de consumo, não medir diretamente o comportamento dos jogadores. Não se trata de uma nova coleta empírica feita nesse artigo, tampouco de uma inferência sobre cada pessoa pobre. Os números devem ser tratados como [[dados secundários citados pelo texto]], sem transformá-los em estimativas atuais.', [c.poverty]);
add(15, 'Que paradoxo entre penetração digital e letramento Games Made Elsewhere apresenta, e por que ele importa para a leitura crítica de interfaces?',
'O texto coloca lado a lado [[86,2% de penetração digital]], 29% de analfabetismo funcional e outros 36% com habilidades elementares no Brasil, conforme as fontes que cita. A interpretação proposta é que acesso amplo não equivale a capacidade igualmente ampla de avaliar práticas e discursos manipulativos. O artigo sugere que mais da metade da população pode enfrentar dificuldades nas habilidades críticas necessárias a essa defesa. São indicadores secundários usados para construir a argumentação, não uma medida individual da experiência de todos os jogadores nem prova de que acesso digital, por si, produza dano.', [c.literacy]);
add(16, 'Por que os percentuais sociais relatados em Games Made Elsewhere não devem ser tratados como resultados de um experimento com jogadores?',
'No trecho, as taxas de pobreza, acesso digital e letramento aparecem acompanhadas de [[referências bibliográficas externas ao próprio levantamento do artigo]]. São mobilizadas para argumentar que precariedade e dificuldades de leitura podem compor vulnerabilidades sistêmicas. O artigo não apresenta ali participantes, manipulação experimental ou medidas de efeito em jogadores. Logo, o uso responsável distingue [[contextualização por dados secundários]] de evidência causal própria: os indicadores ajudam a formular a hipótese de amplificação do dano, mas não quantificam quanto um padrão específico afeta cada grupo.', [c.poverty, c.literacy, c.imagination]);
add(17, 'Quais mecanismos concretos de proteção ao consumidor aparecem na discussão de arbitragem regulatória de Games Made Elsewhere?',
'Além de mencionar marcos menos exigentes ou menos aplicáveis em alguns mercados, o artigo contrasta exigências de [[preço transparente e respeito à vulnerabilidade]] com modelos que obscurecem custos, negam direito de desistência e direcionam ações aos jogadores mais vulneráveis. O argumento é que diferenças de escrutínio e aplicação podem permitir sistemas que enfrentariam maior restrição em outras regiões. Essa descrição deve ser atribuída ao [[contexto argumentativo do artigo de 2025]]: este cartão não verifica a legislação vigente de países nem afirma que proteções sejam uniformes ou ausentes em todos os casos.', [c.arbitrage]);
add(18, 'Como Games Made Elsewhere amplia sua crítica de amostragem WEIRD para além de um único estudo de jogos?',
'O texto relaciona a concentração da pesquisa sobre jogos e padrões enganosos a um viés também discutido na psicologia e na IHC. Menciona que populações WEIRD representam [[12% da população global]], mas dominam estudos da psicologia, conforme a referência citada. O problema argumentado é a [[validade externa para a maioria global]] e a omissão de nuances socioeconômicas. O percentual é um dado secundário usado na discussão; não representa uma contagem realizada pelo artigo nem o percentual de toda a pesquisa de jogos.', [c.weird]);
add(19, 'Na leitura decolonial proposta por Games Made Elsewhere, por que aumentar a diversidade da amostra pode não esgotar o problema?',
'O artigo não apresenta a centralidade WEIRD apenas como descuido metodológico. Interpreta-a como expressão de um [[desequilíbrio sistêmico de poder]], no qual perspectivas, valores e projetos — inclusive padrões enganosos e monetização predatória — podem ser exportados e impostos de modo pouco crítico. Portanto, a questão envolve quem produz e define o projeto, além de quem é observado na pesquisa. Essa é a lente decolonial defendida pelo trabalho; não deve ser confundida com um efeito causal estimado ou com a afirmação de que todo projeto estrangeiro necessariamente cause dano.', [c.weird]);
add(20, 'O que a hipótese de um design seguro em contexto WEIRD tornar-se danoso em outro contexto acrescenta à análise de padrões?',
'O artigo propõe usar a divisão criador-consumidor não apenas para analisar projetos reconhecidamente manipulativos, mas também o [[potencial de mudança de efeito quando um design é implantado em outro contexto]]. Isso impede presumir transferibilidade automática da segurança: condições socioeconômicas, de proteção e de uso fazem parte da análise. Trata-se de uma possibilidade teórica explicitamente apresentada pelo texto, não de prova de que um padrão particular tenha sido seguro em um país e danoso em outro. A pergunta desloca a avaliação da forma isolada da interface para [[sua implantação contextual]].', [c.transfer]);
add(21, 'Que função têm os novos casos de padrões em aplicativos brasileiros na pergunta de Games Made Elsewhere sobre intenção e contexto?',
'O artigo menciona novos casos em aplicativos usados no Brasil, muitos desenvolvidos em outros lugares, como indício de que o contexto [[pode permitir novas formas de exploração]]. Em seguida pergunta se isso é intencional ou coincidente e se tal diferença altera a questão central. A formulação é interrogativa: não prova a intenção das empresas nem transforma a descoberta dos casos em teste causal da divisão criador-consumidor. Sua função é motivar uma lente capaz de examinar [[efeitos estruturais mesmo sem intenção individual demonstrada]].', [c.weird, c.construct]);
add(22, 'Qual é a pergunta de projeto que organiza a extrapolação especulativa de Helena em Games Made Elsewhere?',
'O cenário pergunta o que ocorreria se a divisão criador-consumidor aprisionasse pessoas em um ciclo no qual a [[fuga virtual consumisse recursos essenciais reais e corroesse a integridade cívica]]. O artigo identifica esse procedimento como extrapolação de design especulativo, com artefato de futuro e situação imaginada. Assim, a pergunta orienta uma provocação crítica sobre um extremo possível, e não relata uma ocorrência observada. Sua contribuição é tornar pensável a conexão entre jogo, necessidades materiais e esfera cívica, preservando o [[estatuto ficcional do cenário]].', [c.imagination]);
add(23, 'No cenário especulativo de Helena, por que o jogo inicialmente responde a algo mais amplo do que uma busca por distração?',
'A narrativa apresenta Helena como um arquétipo de vulnerabilidade sistêmica que procura [[controle e realização]] negados por sua realidade precária. O jogo de um grande estúdio situado em país WEIRD promete comunidade e crescimento. Esse início ajuda a mostrar como a atração pode se apoiar em necessidades e aspirações compreensíveis, antes da exploração descrita no restante da ficção. Helena não é participante de uma pesquisa empírica e sua experiência não representa automaticamente todas as pessoas do Sul Global; é uma [[personagem de design especulativo]].', [c.helena]);
add(24, 'Como a proibição do motor de IA no país de origem funciona na ficção de Ouroboros Seed?',
'No cenário imaginado, Helena desconhece que o motor de IA do jogo teria sido [[proibido no país de origem por extração invasiva de dados]] e implantado no Brasil por arbitragem regulatória. Esse elemento dramatiza a segunda dimensão da divisão criador-consumidor: a diferença de condições de implantação permite práticas que encontrariam restrições em outro contexto. É um recurso da narrativa especulativa, não uma denúncia de um motor ou estúdio real, nem evidência de uma proibição concreta. A informação serve para relacionar [[extração de dados e assimetria regulatória]].', [c.helena, c.imagination]);
add(25, 'Como o arco inicial de conforto até dependência é construído no cenário especulativo de Ouroboros Seed?',
'A narrativa descreve laços de interação otimizados por IA que primeiro oferecem [[sensação reconfortante de progresso]] e engajamento profundo. Depois, esse engajamento se transforma em dependência no enredo, e crises personalizadas fazem o avanço depender de grinding intenso ou pagamento para pular a dificuldade. O ponto é a inversão entre apoio aparente e uso instrumental da vulnerabilidade. Não se trata de acompanhamento clínico nem demonstração empírica de dependência: o artigo usa uma [[sequência ficcional para provocar análise de risco]].', [c.loop, c.imagination]);
add(26, 'Por que o preço de $18 no Pay-to-Skip da ficção de Helena é descrito em relação ao gás de cozinha?',
'Na narrativa especulativa, $18 não são renda disponível para Helena: correspondem à parcela mensal destinada ao [[gás de cozinha]]. A equivalência torna visível o conflito entre progresso virtual e necessidade material, em vez de tratar o preço como número abstrato e igual para todos. O texto acrescenta que a impossibilidade de pagar funciona como sua única defesa naquele momento. Esse exemplo não fornece uma taxa real de conversão nem caracteriza o orçamento de jogadores brasileiros; é uma [[comparação construída dentro da ficção]] para expor a relevância do contexto econômico.', [c.loop]);
add(27, 'Como o Community Solidarity Pledge contorna a barreira de renda imediata no cenário especulativo de Helena?',
'Quando ela não pode pagar para superar a crise do jogo, a oferta ficcional não exige dinheiro imediato: propõe [[comprometer parte de um benefício social futuro]]. No enredo, o enquadramento permite ultrapassar a barreira financeira que antes a protegia da compra. A personagem sacrifica parcela de sua rede material de segurança por alívio momentâneo na experiência virtual. O artigo usa essa sequência como extrapolação especulativa; não apresenta um mecanismo comercial real ou ocorrência observada. A análise recai sobre a [[antecipação de recursos essenciais futuros]].', [c.loop, c.imagination]);
add(28, 'Que diferença existe entre a aparência pró-social e o custo futuro do Community Solidarity Pledge na ficção de Ouroboros Seed?',
'A oferta é apresentada como [[compromisso de solidariedade, e não compra]], no momento que a IA ficcional calcula como o auge do desespero. O texto associa essa moldura à preferência por alívio imediato diante de um custo futuro, de modo a atravessar a resistência financeira da personagem. O nome comunitário não elimina o sacrifício de recursos da vida real. Tudo isso pertence ao cenário crítico imaginado: a questão não descreve um experimento sobre vieses nem prova uma taxa de resposta. Ela expõe a [[distância entre linguagem da oferta e consequência material]].', [c.loop]);
add(29, 'Por que a venda do perfil psicológico de Helena amplia o tipo de dano discutido na narrativa especulativa?',
'A ficção não encerra a exploração na monetização. O perfil que identifica [[ansiedades e momentos de baixa resistência cognitiva]] é vendido a campanhas políticas para desinformação direcionada em uma eleição local. Assim, as mesmas vulnerabilidades antes monetizadas pelo jogo são reutilizadas no plano cívico, conectando dados, economia e influência política. Não é um caso empírico nem comprovação de venda de um perfil real; integra a provocação especulativa do artigo sobre possíveis danos que ultrapassam a sessão de jogo e alcançam a [[integridade cívica]].', [c.political, c.imagination]);
add(30, 'No dashboard especulativo, qual é o papel crítico da atribuição de 92% de propensão a escolhas reativas a Helena?',
'O texto afirma que o dashboard de futuro [[desumaniza Helena ao reduzi-la a vulnerabilidades quantificadas]], entre elas uma propensão de 92% a escolhas reativas em contexto de escassez. O número é um elemento do artefato ficcional, não resultado de classificação validada, precisão de um modelo ou prevalência populacional. Sua função é dramatizar como a visão operacional do desenvolvedor pode transformar uma história de precariedade em oportunidade de exploração. Interpretá-lo como dado empírico apagaria justamente o [[caráter especulativo e crítico]] da figura.', [c.dashboard, c.imagination]);
add(31, 'Como os nomes Projected Redistribution, Harvest Equinox e Narrative Anchors funcionam no dashboard especulativo de Ouroboros Seed?',
'O artefato imaginado traduz a retirada de recursos de um distrito da personagem em [[“Projected Redistribution”]], chama uma pressão de monetização de evento sazonal “Harvest Equinox” e classifica táticas manipulativas como “Narrative Anchors”. O artigo usa esses eufemismos corporativos para tornar perceptível a distância entre linguagem operacional e dano material. São rótulos da ficção crítica, não categorias técnicas validadas ou nomes de eventos comerciais observados. A questão permite examinar como [[nomear uma prática pode ocultar sua dimensão ética]] dentro da narrativa.', [c.dashboard]);
add(32, 'Que tensão entre escalabilidade e ética aparece nas notas de desenvolvimento do dashboard especulativo?',
'O artefato ficcional informa que o padrão de vulnerabilidade de Helena corresponde a [[12,7% dos perfis Civic Tier 2]] e sugere replicar o nudge em evento futuro. Ao lado disso, há uma nota de escalonamento ético caso prossiga a cessão a terceiros. O texto narrativo qualifica a revisão ética interna como performática. Esses números e procedimentos são inventados no próprio cenário de design especulativo; não medem uma base real. A tensão crítica é a expansão de uma prática exploratória enquanto a [[linguagem de revisão ética convive com sua operacionalização]].', [c.notes, c.dashboard]);
add(33, 'Como o horário e a privação de sono são instrumentalizados no dashboard especulativo de Helena?',
'O quadro ficcional apresenta uma [[janela de resistência cognitiva entre 2h e 3h]], registra detecção de privação de sono e combina gatilhos de escassez e ansiedade com ofertas de conversão. Também sugere horários para inserção narrativa e micro-recompensas. Esses registros não são medidas clínicas nem um log coletado com uma usuária: pertencem ao dashboard imaginado. A leitura crítica é que um sistema pode ser representado como capaz de [[alinhar o momento de intervenção à vulnerabilidade]], em vez de usar sinais comportamentais para proteção.', [c.timed, c.imagination]);
add(34, 'Por que os elementos financeiros e políticos da ficção de Helena devem ser lidos como uma cadeia, e não como dois episódios independentes?',
'Na narrativa especulativa, as crises e ofertas consomem recursos materiais; o perfil psicológico produzido para explorar ansiedades e baixa resistência é depois reutilizado em [[desinformação política direcionada]]. O texto diz que são as mesmas vulnerabilidades antes monetizadas, conectando as duas etapas. A cadeia ajuda a compreender a pergunta inicial sobre recursos essenciais e integridade cívica. Não é demonstração de que todo jogo produza tal trajetória nem rastreamento empírico: é uma [[construção crítica sobre acúmulo e reutilização de vulnerabilidades]].', [c.loop, c.political, c.imagination]);
add(35, 'Que mudança de unidade de análise as Critical Questions de Games Made Elsewhere propõem para a noção de dano em IHC?',
'As perguntas contrapõem projetos que exploram vieses supostamente universais a projetos que se aproveitam de [[vulnerabilidades estruturais disseminadas]]. Também perguntam quais deveres éticos existem quando essas condições caracterizam mercados inteiros, em vez de bolsões isolados. A mudança é examinar a inserção social e distributiva do projeto, além do evento individual de interação. São perguntas normativas e teóricas provocadas pelo cenário especulativo; não constituem uma estimativa de dano de toda uma população nem uma definição consensual já validada pela comunidade.', [c.ethical, c.provocation]);
add(36, 'Como deve ser interpretada a expressão cognitive colonialism no encerramento das perguntas críticas de Games Made Elsewhere?',
'Ela aparece como uma [[interrogação normativa]] sobre como nomear uma extração de valor massiva e unidirecional do Sul Global, independentemente de intenção, quando o design explora vulnerabilidades estruturais. A expressão faz parte da perspectiva decolonial e da provocação do texto; não é apresentada ali como diagnóstico medido, escala quantitativa ou resultado de comparação experimental. Usá-la com rigor requer manter o encadeamento argumentativo — contexto de criação/consumo, vulnerabilidade e extração — e o [[estatuto especulativo]] do cenário que torna o extremo palpável.', [c.ethical, c.provocation]);
add(37, 'Por que a conclusão especulativa de Ouroboros Seed não pode ser usada como teste de frequência ou inevitabilidade do dano?',
'O próprio artigo chama a distopia de [[provocação]] destinada a tornar palpáveis danos extremos possíveis quando a divisão criador-consumidor é levada ao limite. A seção apresenta um cenário imaginado e um artefato de futuro, não um corpus de jogos ou uma amostra de usuários observados. Por isso, a narrativa pode orientar perguntas, crítica e investigação, mas não informa quantas vezes o encadeamento ocorre, qual sua probabilidade ou se será inevitável. A força da contribuição está em [[expor uma possibilidade ética relevante sem convertê-la em resultado empírico]].', [c.imagination, c.provocation]);
add(38, 'Que responsabilidades permanecem em aberto nas perguntas finais de Games Made Elsewhere, além da coleta de dados em países não-WEIRD?',
'O encerramento pergunta como construir [[parcerias equitativas]] com comunidades do Sul Global e assumir responsabilidade na cocriação de agendas e paradigmas de design que produzam resiliência em vez de aprofundar precariedade. A comunidade não deve aparecer apenas como fonte de dados. O artigo reconhece que isso não é trivial e termina interpelando a disposição da comunidade CHI PLAY para tentar. Portanto, oferece uma convocação e uma agenda ética aberta, [[não um protocolo participativo já implementado e avaliado]].', [c.partnership]);

add(39, 'Como a lente do creator-consumer divide pode aprofundar a avaliação documentada de riscos do princípio 1.6 de Safety by Design?',
'Como [[síntese para arguição]], a avaliação de riscos do SbD pode ser interrogada sobre condições de implantação, não apenas sobre uma interface abstrata. O princípio 1.6 pede avaliações documentadas, remediação e auditorias quando perfis de risco mudam; Games Made Elsewhere chama atenção para vulnerabilidades sistêmicas preexistentes e para a possibilidade de um design seguro em contexto WEIRD ser danoso em outro. A ponte sugere perguntar quais usuários e condições foram considerados e o que muda ao transferir o serviço. Nenhum texto demonstra que aplicar essa comparação elimine danos: ela organiza [[perguntas contextuais para uma avaliação preventiva]].', [c.construct, c.transfer], [r.sbdRisk]);
add(40, 'Como comparar a escolha de Helena na ficção de Games Made Elsewhere com autonomia e segurança por padrão em Safety by Design?',
'O princípio 2 do SbD relaciona autonomia a dignidade, interesses do usuário e controle efetivo; o subprincípio 2.1 recomenda níveis mais seguros por padrão e rejeita exigir o sacrifício de privacidade ou segurança para acessar um serviço. Na ficção de Helena, a oferta é construída para ultrapassar uma barreira financeira em momento de vulnerabilidade. A [[comparação analítica]] distingue possibilidade operacional de escolher e condições materiais para exercer agência, sem presumir incapacidade individual de quem vive precariedade. Isso não é uma avaliação empírica de um controle SbD: a narrativa é especulativa e as orientações SbD não comprovam, sozinhas, [[autonomia ou eficácia em toda situação]].', [c.loop, c.imagination], [r.sbdAgency]);
add(41, 'Que contraste pode ser feito entre a revisão ética performática do dashboard especulativo e a responsabilização do princípio 1.1 de Safety by Design?',
'No artefato ficcional de Games Made Elsewhere, a exploração é quantificada e potencialmente replicada enquanto a mensagem política é remetida a uma revisão ética que o texto chama de performática. O princípio 1.1 do SbD pede [[pessoas ou equipes nomeadas e responsabilizadas]] por criação, avaliação, implantação e operação da política de segurança ao longo do ciclo do serviço. A síntese contrasta um rótulo de revisão com atribuições mensuráveis e capacidade de decisão. Não prova que uma estrutura formal sempre funcione; torna explícita a pergunta sobre [[quem pode impedir ou corrigir a prática]], em vez de apenas registrar sua existência.', [c.dashboard, c.notes], [r.sbdAccountable]);
add(42, 'Como a crítica decolonial de Games Made Elsewhere dialoga com as reservas de Safety by Design contra uma abordagem one-size-fits-all?',
'Games Made Elsewhere critica a exportação pouco crítica de valores e projetos WEIRD e pergunta pela transferibilidade de um design considerado seguro. Na consulta SbD, participantes destacam que serviços diferem em projeto, função, cultura, uso e modelo de negócio, e que uma mesma funcionalidade pode não produzir impacto positivo em outro contexto. A [[síntese entre os textos]] apoia questionar uma checklist universal aplicada sem exame de contexto. As perspectivas não são idênticas: a primeira explicita assimetria de poder e a segunda registra preocupações da consulta. A aproximação não estabelece um [[método intercultural já validado]].', [c.weird, c.transfer], [r.sbdInclusive]);
add(43, 'Como o custo essencial e o compromisso financeiro futuro da ficção de Helena ampliam uma leitura das compras on-line listadas no documento local do Art.48?',
'O §10 do documento local lista a possibilidade de compras on-line entre funcionalidades consideradas na atribuição de classificação. Na narrativa especulativa de Helena, o preço é relacionado ao gás de cozinha e a oferta posterior compromete benefício futuro, mostrando por que o [[contexto material de uma compra]] pode importar para a análise ética. A correlação não transforma o inciso em avaliação de dano econômico, nem afirma vigência ou eficácia jurídica do documento. Também não faz do exemplo ficcional um caso observado: é uma ponte para distinguir [[presença de funcionalidade classificável e mecanismo contextual de exploração]].', [c.loop, c.imagination], [r.artPurchase]);
add(44, 'Que relação pode ser construída entre o reaproveitamento do perfil psicológico de Helena e os incisos sobre dados e privacidade do documento local Art.48?',
'O documento local menciona compartilhamento ou fornecimento de dados pessoais e desativação de mecanismos de privacidade entre fatores de classificação. A ficção de Helena apresenta um perfil de ansiedades e baixa resistência reutilizado para desinformação política. A [[leitura conjunta]] distingue identificar uma funcionalidade de examinar a finalidade e o encadeamento de seu uso: o dano especulado não se encerra na coleta ou na sessão de jogo. Isso não demonstra que os incisos impeçam a prática nem verifica legislação vigente. O caso de Helena continua [[artefato de design especulativo]], não prova de exploração real de dados.', [c.political, c.imagination], [r.artPurchase]);
add(45, 'Por que a correlação entre loops de Helena e funcionalidades de uso prolongado do Art.48 não autoriza classificar toda gamificação como padrão enganoso?',
'O documento local inclui recomendações, recompensas variáveis, gamificação e outras funcionalidades de manutenção prolongada do uso na consideração classificatória. Na ficção de Ouroboros Seed, loops são associados a crises personalizadas e exploração de recursos materiais. A [[síntese]] deve conservar as unidades de análise: listar uma funcionalidade não determina, por si, sua implementação, intenção ou efeito; a narrativa constrói um uso extremo e especulativo dessas relações. A pergunta útil é como a mecânica é implantada e com que consequência contextual, sem afirmar que [[toda ocorrência de gamificação seja exploratória]] ou que o documento tenha comprovado o dano.', [c.loop, c.imagination], [r.artRetention]);
add(46, 'Como distinguir identificação de representantes no §13 do documento Art.48 e enfrentamento da arbitragem regulatória discutida em Games Made Elsewhere?',
'O §13 do documento local pede informações claras e atualizadas sobre representantes para comunicação institucional, regulatória e responsabilização. Games Made Elsewhere discute diferenças na força e aplicação das proteções como condição da arbitragem regulatória. A [[comparação]] sugere que haver um interlocutor identificável pode ser relevante à responsabilização, mas não demonstra, por si, fiscalização efetiva, simetria de proteção ou resolução das lacunas descritas. O cartão não verifica vigência jurídica do documento nem atualiza a situação dos países: distingue [[visibilidade institucional e capacidade concreta de aplicação]], mantendo a natureza argumentativa do artigo.', [c.arbitrage], [r.artRepresentation]);
add(47, 'Como a vulnerabilidade contextual discutida em Games Made Elsewhere tensiona a proposta de alertas em tempo real de From Understanding to Intervention?',
'A agenda propõe ferramentas de assistência que ampliem agência por informação contextual, sem induzir disfarçadamente a “melhor escolha”; também alerta para fadiga de notificações, falsos positivos e intrusão. Games Made Elsewhere aponta redução da vigilância crítica e dificuldades de letramento em condições sociais de vulnerabilidade. A [[síntese]] permite perguntar se um alerta é compreensível e acionável naquele contexto, em vez de presumir que informar é suficiente. Os trabalhos não testam juntos essa hipótese: nem a vulnerabilidade é igual para todos nem as ferramentas propostas na agenda têm [[eficácia universal demonstrada]].', [c.guard, c.literacy], [r.agendaPlayer]);
add(48, 'Como automação indiferente e limites de decisão dos desenvolvedores ajudam a distribuir responsabilidade ao correlacionar Games Made Elsewhere e a agenda de intervenção?',
'A divisão criador-consumidor admite exploração por direcionamento deliberado ou automação indiferente. A agenda observa que decisões de monetização podem ser tomadas por acionistas, executivos e equipes de produto orientadas a KPIs, deixando pouca autonomia aos desenvolvedores. Como [[comparação analítica]], isso impede localizar toda a responsabilidade em conhecimento técnico individual e convida a examinar quem decide objetivos, métricas e implantação. A agenda pede mais pesquisa empírica sobre essas pressões; não oferece um retrato de toda empresa. A relação aponta um problema de [[governança e poder decisório]], sem isentar automaticamente qualquer papel.', [c.construct], [r.agendaOrganization]);
add(49, 'Como o dashboard especulativo de Helena e a proposta de avaliação de impacto da agenda de intervenção mostram usos eticamente distintos de dados de jogo?',
'No dashboard ficcional, dados sobre escassez, resistência cognitiva e comportamento servem a gatilhos de exploração. A agenda propõe combinar telemetria e análise comportamental com instrumentos de experiência e evidências qualitativas para identificar autonomia comprometida e avaliar alternativas, quando eticamente apropriado. A [[síntese]] não afirma que telemetria seja boa ou má por natureza: contrasta finalidades e critérios de uso. O dashboard não é sistema real e a proposta de avaliação não é eficácia demonstrada. A questão é se o conhecimento sobre o jogador orienta [[proteção e avaliação de impacto ou extração de vulnerabilidade]].', [c.dashboard, c.imagination], [r.agendaMeasure]);
add(50, 'Como Untranslation no estudo de aplicativos brasileiros se relaciona ao paradoxo de acesso digital e letramento de Games Made Elsewhere?',
'Interact descreve o uso de idioma estrangeiro para obscurecer informação quando o restante do aplicativo está na língua do usuário e aponta a relevância da proficiência em inglês. Games Made Elsewhere discute a coexistência de alto acesso digital e dificuldades de letramento como parte da vulnerabilidade contextual. A [[correlação argumentativa]] mostra por que disponibilizar informação não equivale a torná-la compreensível. Não se deve identificar letramento funcional e proficiência em língua estrangeira como a mesma medida, nem inferir um efeito causal comum não testado. A ponte é a [[compreensibilidade efetiva da interação em seu contexto]].', [c.literacy], [r.intLanguage]);
add(51, 'Por que a observação de dez minutos no Interact e o encadeamento prolongado da ficção de Helena exigem inferências diferentes?',
'Interact delimita o corpus a aplicativos gratuitos em alta e a dez minutos do primeiro uso, advertindo que outras interações e padrões podem surgir em uso prolongado ou não aparecer no emulador. A ficção de Helena constrói uma sequência de engajamento, crises e reutilização do perfil para explorar consequências possíveis. A [[comparação metodológica]] distingue presença observada em uma janela curta de trajetória especulativa de dano. Nenhuma frente completa empiricamente a outra: a auditoria não prova a cadeia imaginada, e a ficção não mede o que ficou fora dos dez minutos. Elas sugerem [[questões adicionais de investigação]].', [c.loop, c.political, c.imagination], [r.intLimits]);
add(52, 'Como combinar o corpus contextual do Interact com a crítica de transferibilidade de Games Made Elsewhere sem converter prevalência de apps em prevalência de jogos?',
'O Interact seleciona aplicativos Android gratuitos e em alta no Brasil, com categorias e critérios próprios, e discute influências socioeconômicas, educacionais e socioculturais na manifestação dos padrões. Games Made Elsewhere pergunta pela transferência de conhecimento e efeitos entre contextos de criação e consumo. A [[síntese]] permite usar a auditoria como motivação para investigação contextual, mantendo seu recorte. Seus resultados não são uma estimativa representativa de todos os jogos ou mercados, nem validam causalmente a lente teórica. É necessário distinguir [[contexto compartilhado e equivalência de corpus]], que os textos não estabelecem.', [c.weird, c.transfer], [r.intCorpus, r.intContext]);
add(53, 'Como comparar a exploração por automação indiferente de Games Made Elsewhere com a escolha intencional de Radiant Patterns em Operationalizing?',
'A primeira lente admite que vulnerabilidades sejam capitalizadas sem direcionamento deliberado individual. Operationalizing define RPs como escolhas conscientes e intencionalmente implementadas para permitir objetivos de desenvolvimento sem comprometer de forma significativa o bem-estar fundamental, evitando diminuir autonomia, competência e vínculo. A [[comparação]] distingue ausência de intenção maliciosa de compromisso preventivo explícito. Não basta chamar um projeto de ético: a definição exige critérios relativos a riscos previsíveis e frustração de necessidades. Essa ponte não valida a eficácia de um padrão específico; explicita a [[diferença entre indiferença à consequência e seleção preventiva do design]].', [c.construct], [r.opDefinition]);
add(54, 'Como a relação grinding/pagamento da ficção de Helena pode ser contrastada com Watch For do padrão World Creation em Operationalizing?',
'Na ficção de Helena, crises fazem o progresso depender de grinding intenso ou Pay-to-Skip, e o custo concorre com recursos essenciais. Em World Creation, Watch For orienta não condicionar ferramentas criativas fundamentais a grinding excessivo ou pagamento direto, para não frustrar autonomia e competência; monetização pode incidir sobre melhorias opcionais ou ofertas adjacentes. A [[síntese]] identifica uma tensão entre atividade central e barreira econômica, sem afirmar que as duas situações sejam o mesmo gênero ou mecânica. O cenário é especulativo e a orientação não prova eficácia comercial ou psicológica: são [[critérios para analisar implementação]].', [c.loop, c.imagination], [r.opGrind]);
add(55, 'Como a variabilidade de percepção discutida em Operationalizing reforça a cautela de Games Made Elsewhere sobre segurança transferível entre contextos?',
'Games Made Elsewhere propõe que um design considerado seguro em contexto WEIRD possa tornar-se danoso em outro. Operationalizing reconhece que letramento, experiência e perfil do jogador afetam percepção, não permite confiança excessiva em eficácia contextual e informa que ainda não houve avaliação com jogadores dos efeitos diretos em bem-estar. A [[leitura conjunta]] não demonstra que RPs falhem no Sul Global: exige investigar quem experimenta o padrão, em que condições e com quais efeitos. A relação é um argumento para [[validação contextual]], preservando a diferença entre hipótese teórica e resultados efetivamente obtidos.', [c.transfer], [r.opPerception, r.opLimits]);
add(56, 'Como a distinção entre níveis universais e variantes contextuais em Beyond Dark Patterns pode dialogar com a lente criador-consumidor?',
'Beyond Dark Patterns esclarece que L1–L3 são uma base metodológica, não uma alegação de experiência universal; variantes adaptam implementações a condições de jogo preservando a referência ética de não frustração. Games Made Elsewhere chama atenção para contextos sociais de criação e consumo e transferência de segurança. A [[síntese]] propõe perguntar se a adaptação considera também condições sociais relevantes, sem afirmar que as variantes do framework já resolvam a assimetria geopolítica. São dimensões relacionadas, mas não idênticas: [[contexto de gameplay não substitui investigação socioeconômica]].', [c.construct, c.transfer], [r.hciContext]);
add(57, 'Que contraste de projeto pode ser construído entre os loops de retenção da ficção de Helena e os níveis de Open Gate em Beyond Dark Patterns?',
'O cenário especulativo articula conforto, dependência, crises e custos para continuar progredindo. Beyond Dark Patterns apresenta Open Gate com L1 de salvamento automático, L2 de parada intencional e L3 de feedback visual de realização. A [[comparação]] usa preservação do progresso e possibilidade de parar como contrapontos conceituais a um encadeamento que instrumentaliza permanência. Não demonstra que adicionar salvamento elimine exploração financeira ou política, nem que Open Gate tenha sido testado na situação de Helena: o cenário é ficcional e os níveis oferecem [[critérios estruturais, não garantia de bem-estar]].', [c.loop, c.imagination], [r.hciGate]);
add(58, 'Como relacionar parceria decolonial, verificação colaborativa de RPs e engajamento aberto do princípio 3.3 de Safety by Design sem confundir participação com consenso universal?',
'Games Made Elsewhere pede cocriação de agendas com comunidades do Sul Global. Beyond Dark Patterns distingue uma perspectiva focada de nove especialistas de consenso global e exige recorrência e verificação coletiva de candidatos. SbD 3.3 recomenda engajamento aberto com usuários e especialistas externos, reconhecendo consequências imprevistas até em ferramentas bem-intencionadas. A [[síntese de três frentes]] aproxima participação, crítica e revisão contextual, mas conserva seus limites: consulta não equivale automaticamente a parceria equitativa, consenso de especialistas não representa todas as comunidades e verificação estrutural não prova efeito longitudinal. A pergunta é [[quem participa e que evidência pode revisar uma decisão]].', [c.partnership], [r.hciConsensus, r.hciCandidate], [r.sbdOpen]);

if (cards.length !== 50 || new Set(cards.map(card => card.id)).size !== 50) throw Error('Expected 50 unique candidates');
const published = JSON.parse(fs.readFileSync(path.join(root, 'src/data/cards.json'), 'utf8').replace(/^\uFEFF/, ''));
const oldQuestions = new Map(published.map(card => [card.question.normalize('NFKC').toLocaleLowerCase('pt-BR'), card.id]));
for (const card of cards) {
  const existingId = oldQuestions.get(card.question.normalize('NFKC').toLocaleLowerCase('pt-BR'));
  if (existingId && existingId !== card.id) throw Error(`Repeated published question: ${card.id}`);
}
fs.writeFileSync(path.join(out, `${docs.chip.articleId}.json`), JSON.stringify(cards, null, 2) + '\n', 'utf8');
console.log(`${cards.length} candidatos CHIP: ${cards.filter(c => c.kind === 'direct').length} diretos, ${cards.filter(c => c.kind === 'synthesis').length} sínteses. Somente autoria; aprovação independente pendente.`);
